fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // We want at most maxsplit splits, which produces at most maxsplit+1 parts.
    // rsplitn takes the maximum number of resulting parts.
    let max_parts = (maxsplit as usize) + 1;

    a.into_iter()
     .map(|s| {
         // rsplitn yields at most max_parts substrings from the right.
         let mut parts: Vec<String> = s
             .rsplitn(max_parts, &sep)
             .map(|substr| substr.to_string())
             .collect();
         // rsplitn returns them from right-to-left; reverse to get left-to-right.
         parts.reverse();
         parts
     })
     .collect()
}

#[cfg(test)]
mod tests {
    use super::rsplit;

    #[test]
    fn test_basic() {
        let data = vec![
            "a_b_c".to_string(),
            "hello".to_string(),
            "".to_string(),
            "one::two::three".to_string(),
        ];
        let sep = "_".to_string();
        assert_eq!(
            rsplit(data.clone(), sep.clone(), 1),
            vec![
                vec!["a_b".to_string(), "c".to_string()],
                vec!["hello".to_string()],
                vec!["".to_string()],
                vec!["one::two::three".to_string()],
            ]
        );

        let sep2 = "::".to_string();
        assert_eq!(
            rsplit(data, sep2.clone(), 2),
            vec![
                vec!["a_b_c".to_string()],
                vec!["hello".to_string()],
                vec!["".to_string()],
                vec![
                    "one".to_string(),
                    "two".to_string(),
                    "three".to_string(),
                ],
            ]
        );

        // maxsplit = 0 → no splits at all
        let data2 = vec!["x_y_z".to_string()];
        let out = rsplit(data2.clone(), "_".to_string(), 0);
        assert_eq!(out, vec![vec![data2[0].clone()]]);
    }
}